#!/usr/bin/env python3
"""Fail-closed team preflight enforced before local mutation tools."""

from __future__ import annotations

import hashlib
import json
import os
import re
import shlex
import subprocess
import sys
import tempfile
from pathlib import Path

import marketplace_paths


OWNER_RE = re.compile(
    r"^# Generated by Agent Marketplace ([a-z0-9]+(?:-[a-z0-9]+)*); do not edit by hand\.$"
)
MUTATION_TOOLS = {"Write", "Edit", "MultiEdit", "apply_patch", "Bash",
                  "exec_command", "shell"}
READ_ONLY_DIAGNOSTICS = {
    ("claude", "plugin", "list", "--json"),
    ("codex", "plugin", "list", "--json"),
}
UPGRADE_STATUSES = {
    "AGENT_MARKETPLACE_UPGRADE_REQUIRED_READY",
    "AGENT_MARKETPLACE_UPGRADE_REQUIRED_BLOCKED",
    "AGENT_MARKETPLACE_UPGRADE_RECOVERY_REQUIRED",
    "AGENT_MARKETPLACE_UPGRADE_COMPLETE_RESTART_REQUIRED",
    "AGENT_MARKETPLACE_UPGRADING",
    "AGENT_MARKETPLACE_PROJECT_UPGRADE_PR_PENDING",
    "AGENT_MARKETPLACE_ENVIRONMENT_RECONCILE_REQUIRED",
    "AGENT_MARKETPLACE_RECONCILE_DEFERRED_ACTIVE_WORK",
    "AGENT_MARKETPLACE_PROJECT_UPGRADE_CHOICE_REQUIRED",
}
UPGRADE_BRANCH_RE = re.compile(
    r"^agent-marketplace/upgrade-[A-Za-z0-9][A-Za-z0-9._-]*$"
)
GENERATED_PROJECT_HEADER_RE = re.compile(
    r"^<!-- generated by agent-marketplace [a-z0-9]+(?:-[a-z0-9]+)* "
    r"for (?:codex|claude|shared); do not edit by hand -->$"
)
PATCH_PATH_RE = re.compile(r"^\*\*\* (?:Add|Update|Delete) File: (.+)$")
DIRECT_WRITERS = {"rm", "mv", "cp", "tee", "touch", "truncate", "sed", "perl"}


def data_dir() -> Path:
    return marketplace_paths.marketplace_home()


def plugin_root() -> Path:
    return Path(__file__).resolve().parents[1]


def plugin_name() -> str:
    root = plugin_root()
    for manifest in (
        root / ".codex-plugin" / "plugin.json",
        root / ".claude-plugin" / "plugin.json",
    ):
        try:
            value = json.loads(manifest.read_text(encoding="utf-8")).get("name", "")
            if value:
                return str(value)
        except Exception:
            continue
    return "unknown-team"


def session_state_path(session_id: str) -> Path:
    digest = hashlib.sha256(session_id.encode("utf-8")).hexdigest()
    return data_dir() / "sessions" / f"{digest}.json"


def session_ready(session_id: str) -> bool:
    if not session_id:
        return False
    try:
        state = json.loads(session_state_path(session_id).read_text(encoding="utf-8"))
        return state.get("session_id") == session_id and state.get("pmo_ready") is True
    except Exception:
        return False


def session_contract(session_id: str) -> str:
    if not session_id:
        return ""
    try:
        state = json.loads(session_state_path(session_id).read_text(encoding="utf-8"))
        return str(state.get("contract_sha256_at_start", "")) \
            if state.get("session_id") == session_id else ""
    except Exception:
        return ""


def project_root(cwd: str) -> Path | None:
    try:
        current = Path(cwd).resolve()
    except Exception:
        return None
    for candidate in (current, *current.parents):
        if (candidate / ".git").exists():
            return candidate
    return None


def conflicting_team(cwd: str, current_team: str) -> str:
    root = project_root(cwd)
    if root is None:
        return ""
    workspace = "workspace"
    config = root / workspace / "config.json"
    if not config.is_file():
        candidates = sorted(root.glob("*/config.json"))
        if len(candidates) == 1:
            config = candidates[0]
    try:
        data = json.loads(config.read_text(encoding="utf-8"))
        owner = marketplace_paths.team_from_config(data)
        if owner and owner != current_team:
            return str(owner)
    except FileNotFoundError:
        pass
    except Exception:
        return "unreadable-project-config"
    agents = root / ".codex" / "agents"
    if agents.is_dir():
        for path in sorted(agents.glob("*.toml")):
            try:
                first = path.read_text(
                    encoding="utf-8", errors="replace"
                ).splitlines()[0]
            except (OSError, IndexError):
                continue
            match = OWNER_RE.fullmatch(first)
            if match and match.group(1) != current_team:
                return match.group(1)
    return ""


def register(team: str) -> None:
    launcher = data_dir() / "bin" / "marketplace_run.py"
    if not launcher.is_file():
        return
    subprocess.run(
        [sys.executable, str(launcher), "register", "--plugin", team,
         "--root", str(plugin_root())],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=False,
    )


def upgrade_status(cwd: str) -> dict:
    launcher = data_dir() / "bin" / "pmo_cli.py"
    root = project_root(cwd)
    if not launcher.is_file() or root is None:
        return {}
    command = [sys.executable, str(launcher), "upgrade", "status",
               "--project-root", str(root), "--json"]
    completed = subprocess.run(
        command,
        capture_output=True, text=True, check=False, timeout=60,
    )
    try:
        value = json.loads(completed.stdout)
    except (json.JSONDecodeError, TypeError):
        value = None
    if not isinstance(value, dict) or not value.get("status"):
        return {
            "status": "AGENT_MARKETPLACE_UPGRADE_REQUIRED_BLOCKED",
            "blockers": ["UPGRADE_STATUS_UNAVAILABLE"],
        }
    return value


def environment_status(cwd: str) -> dict:
    launcher = data_dir() / "bin" / "pmo_cli.py"
    root = project_root(cwd)
    if not launcher.is_file() or root is None:
        return {}
    completed = subprocess.run(
        [sys.executable, str(launcher), "project", "environment-status",
         "--project-root", str(root), "--json"],
        capture_output=True, text=True, check=False, timeout=60,
    )
    try:
        value = json.loads(completed.stdout)
    except (json.JSONDecodeError, TypeError):
        value = None
    return value if isinstance(value, dict) else {
        "status": "AGENT_MARKETPLACE_UPGRADE_REQUIRED_BLOCKED",
        "blockers": ["ENVIRONMENT_STATUS_UNAVAILABLE"],
    }


def refresh_session_readiness(session_id: str, status: str) -> bool:
    if not session_id or not status:
        return False
    path = session_state_path(session_id)
    try:
        state = json.loads(path.read_text(encoding="utf-8"))
        if state.get("session_id") != session_id:
            return False
        state["pmo_ready"] = status == "AGENT_MARKETPLACE_CURRENT"
        state["upgrade_status"] = status
        fd, temporary = tempfile.mkstemp(dir=str(path.parent), prefix=f".{path.name}.")
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(json.dumps(state, sort_keys=True) + "\n")
        os.replace(temporary, path)
        return state["pmo_ready"]
    except Exception:
        return False


def is_upgrade_command(payload: dict) -> bool:
    if str(payload.get("tool_name", "")) not in {"Bash", "exec_command", "shell"}:
        return False
    tool_input = payload.get("tool_input", {})
    command = tool_input.get("command", tool_input.get("cmd", "")) \
        if isinstance(tool_input, dict) else ""
    if not isinstance(command, str):
        return False
    try:
        argv = shlex.split(command, posix=True)
    except ValueError:
        return False
    if any(token in {";", "|", "||", "&&", ">", ">>", "<"} for token in argv):
        return False
    launcher = (data_dir() / "bin" / "pmo_cli.py").resolve()
    offset = 0
    if argv:
        try:
            if Path(argv[0]).expanduser().resolve(strict=False) == launcher:
                offset = 1
            elif len(argv) > 1 \
                    and re.fullmatch(r"python(?:3(?:\.\d+)?)?", Path(argv[0]).name) \
                    and Path(argv[1]).expanduser().resolve(strict=False) == launcher:
                offset = 2
        except OSError:
            return False
    if offset == 0:
        return False
    return len(argv) > offset + 1 and argv[offset] == "upgrade" \
        and argv[offset + 1] in {
            "status", "prepare-branch", "plan", "apply", "recover",
        }


def is_environment_command(payload: dict) -> bool:
    if str(payload.get("tool_name", "")) not in {"Bash", "exec_command", "shell"}:
        return False
    tool_input = payload.get("tool_input", {})
    command = tool_input.get("command", tool_input.get("cmd", "")) \
        if isinstance(tool_input, dict) else ""
    try:
        argv = shlex.split(str(command), posix=True)
    except ValueError:
        return False
    launcher = (data_dir() / "bin" / "pmo_cli.py").resolve()
    offset = 0
    try:
        if argv and Path(argv[0]).expanduser().resolve(strict=False) == launcher:
            offset = 1
        elif len(argv) > 1 and re.fullmatch(
            r"python(?:3(?:\.\d+)?)?", Path(argv[0]).name
        ) and Path(argv[1]).expanduser().resolve(strict=False) == launcher:
            offset = 2
    except OSError:
        return False
    return argv[offset:offset + 2] in (
        ["project", "environment-status"], ["project", "attach"],
    )


def active_work_git_change(payload: dict, cwd: str, environment: dict) -> bool:
    if str(payload.get("tool_name", "")) not in {"Bash", "exec_command", "shell"}:
        return False
    root = project_root(cwd)
    if root is None:
        return False
    local_active = any(
        value.get("type") == "work_order"
        and Path(str(value.get("worktree", ""))).resolve() == root
        for value in environment.get("active_work", [])
        if isinstance(value, dict) and value.get("worktree")
    )
    if not local_active:
        return False
    tool_input = payload.get("tool_input", {})
    command = tool_input.get("command", tool_input.get("cmd", "")) \
        if isinstance(tool_input, dict) else ""
    try:
        argv = shlex.split(str(command), posix=True)
    except ValueError:
        return False
    return len(argv) >= 2 and argv[0] == "git" and argv[1] in {
        "pull", "merge", "rebase",
    }


def is_upgrade_target_command(payload: dict, cwd: str, status: dict) -> bool:
    blockers = {str(value) for value in status.get("blockers", [])}
    target_blockers = {
        value for value in blockers if value.startswith("UPGRADE_TARGET_REQUIRED:")
    }
    if len(target_blockers) != 1 or blockers != target_blockers:
        return False
    if str(payload.get("tool_name", "")) not in {"Bash", "exec_command", "shell"}:
        return False
    tool_input = payload.get("tool_input", {})
    command = tool_input.get("command", tool_input.get("cmd", "")) \
        if isinstance(tool_input, dict) else ""
    try:
        argv = shlex.split(command, posix=True)
    except (TypeError, ValueError):
        return False
    target = next(iter(target_blockers)).split(":", 1)[1]
    return argv in (["git", "switch", target], ["git", "checkout", target]) \
        and project_root(cwd) is not None


def latest_plan_files(cwd: str) -> set[str]:
    root = project_root(cwd)
    plans = data_dir() / "upgrades" / "plans"
    if root is None or not plans.is_dir():
        return set()
    matches = []
    for path in plans.glob("*.json"):
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
            if Path(value.get("project", {}).get("root", "")).resolve() == root:
                matches.append((path.stat().st_mtime_ns, value))
        except Exception:
            continue
    if not matches:
        return set()
    return {str(value) for value in max(matches, key=lambda item: item[0])[1]
            .get("project_files", [])}


def git_changed_files(
    root: Path, *, cached: bool, paths: set[str] | None = None,
) -> set[str] | None:
    command = ["git", "diff", "--name-only", "-z"]
    if cached:
        command.append("--cached")
    if paths:
        command.extend(["--", *sorted(paths)])
    completed = subprocess.run(
        command, cwd=root, capture_output=True, check=False, timeout=30,
    )
    if completed.returncode != 0:
        return None
    return {
        value.decode("utf-8", errors="surrogateescape")
        for value in completed.stdout.split(b"\0") if value
    }


def is_project_upgrade_git_command(payload: dict, cwd: str) -> bool:
    if str(payload.get("tool_name", "")) not in {"Bash", "exec_command", "shell"}:
        return False
    tool_input = payload.get("tool_input", {})
    command = tool_input.get("command", tool_input.get("cmd", "")) \
        if isinstance(tool_input, dict) else ""
    try:
        argv = shlex.split(command, posix=True)
    except (TypeError, ValueError):
        return False
    if any(token in {";", "|", "||", "&&", ">", ">>", "<"} for token in argv):
        return False
    root = project_root(cwd)
    planned = latest_plan_files(cwd)
    if root is None or not planned:
        return False
    if argv in (
        ["git", "status", "--short"],
        ["git", "diff", "--stat"],
        ["git", "diff", "--cached", "--stat"],
    ):
        return True
    branch = subprocess.run(
        ["git", "symbolic-ref", "--short", "-q", "HEAD"], cwd=root,
        capture_output=True, text=True, check=False, timeout=30,
    ).stdout.strip()
    if argv in (
        ["git", "push", "-u", "origin", branch],
        ["git", "push", "--set-upstream", "origin", branch],
    ):
        return bool(branch and UPGRADE_BRANCH_RE.fullmatch(branch))
    if len(argv) >= 3 and argv[:3] == ["gh", "pr", "create"]:
        return True
    if len(argv) > 3 and argv[:3] == ["git", "diff", "--"]:
        return set(argv[3:]) <= planned
    if len(argv) > 4 and argv[:4] == ["git", "diff", "--cached", "--"]:
        return set(argv[4:]) <= planned
    if len(argv) > 3 and argv[:3] == ["git", "add", "--"]:
        return set(argv[3:]) <= planned
    if argv not in (
        ["git", "commit", "-m", "chore: apply Agent Marketplace upgrade"],
        ["git", "commit", "--message", "chore: apply Agent Marketplace upgrade"],
    ):
        return False
    staged = git_changed_files(root, cached=True)
    unstaged = git_changed_files(root, cached=False, paths=planned)
    return staged == planned and unstaged == set()


def deny(message: str) -> int:
    print(f"agent-marketplace team gate: {message}", file=sys.stderr)
    return 2


def is_read_only_diagnostic(payload: dict) -> bool:
    """Allow only exact plugin inventory commands through a shell hook.

    A strict argv comparison deliberately rejects redirects, pipelines,
    command chaining, environment prefixes, and extra flags.
    """
    if str(payload.get("tool_name", "")) not in {"Bash", "exec_command", "shell"}:
        return False
    tool_input = payload.get("tool_input", {})
    if not isinstance(tool_input, dict):
        return False
    command = tool_input.get("command", tool_input.get("cmd", ""))
    if not isinstance(command, str):
        return False
    try:
        argv = tuple(shlex.split(command, posix=True))
    except ValueError:
        return False
    return argv in READ_ONLY_DIAGNOSTICS


def managed_project_paths(root: Path) -> set[Path]:
    paths: set[Path] = set()
    for config_path in sorted(root.glob("*/config.json")):
        try:
            config = json.loads(config_path.read_text(encoding="utf-8"))
            state = config.get("agent_marketplace", {})
            surfaces = state.get("managed_surfaces", {}) \
                if isinstance(state, dict) else {}
            if not isinstance(surfaces, dict):
                continue
            for key in surfaces:
                relative = str(key)
                if relative.startswith("shared:"):
                    relative = relative[len("shared:"):]
                elif ":" in relative and (
                    "#" not in relative
                    or relative.index(":") < relative.index("#")
                ):
                    relative = relative.split(":", 1)[1]
                relative = relative.split("#", 1)[0]
                if relative and not Path(relative).is_absolute():
                    paths.add((root / relative).resolve(strict=False))
            paths.add(config_path.resolve(strict=False))
            break
        except Exception:
            continue
    for relative in ("AGENTS.md", "CLAUDE.md"):
        path = root / relative
        try:
            first = path.read_text(
                encoding="utf-8", errors="replace"
            ).splitlines()[0]
        except (OSError, IndexError):
            continue
        if GENERATED_PROJECT_HEADER_RE.fullmatch(first):
            paths.add(path.resolve(strict=False))
    return paths


def payload_paths(payload: dict, cwd: str) -> set[Path]:
    raw_tool = str(payload.get("tool_name", ""))
    raw_input = payload.get("tool_input", {})
    values: list[str] = []
    if raw_tool in {"Write", "Edit", "MultiEdit"} and isinstance(raw_input, dict):
        value = raw_input.get("file_path", raw_input.get("path", ""))
        if value:
            values.append(str(value))
    elif raw_tool == "apply_patch":
        patch = raw_input if isinstance(raw_input, str) else ""
        if isinstance(raw_input, dict):
            patch = next((
                str(raw_input[key]) for key in ("patch", "input", "text")
                if isinstance(raw_input.get(key), str)
            ), "")
        values.extend(
            match.group(1).strip()
            for line in patch.splitlines()
            if (match := PATCH_PATH_RE.match(line)) is not None
        )
    elif raw_tool in {"Bash", "exec_command", "shell"} and isinstance(raw_input, dict):
        command = raw_input.get("command", raw_input.get("cmd", ""))
        try:
            argv = shlex.split(str(command), posix=True)
        except ValueError:
            return set()
        if not argv:
            return set()
        executable = Path(argv[0]).name
        if executable not in DIRECT_WRITERS and not any(
            token in {">", ">>"} for token in argv
        ):
            return set()
        values.extend(
            token for token in argv[1:]
            if token not in {">", ">>", "--"} and not token.startswith("-")
        )
    base = Path(cwd).resolve()
    result: set[Path] = set()
    for value in values:
        try:
            path = Path(value).expanduser()
            result.add((path if path.is_absolute() else base / path).resolve(strict=False))
        except (OSError, RuntimeError):
            continue
    return result


def direct_managed_target(payload: dict, cwd: str) -> str:
    root = project_root(cwd)
    if root is None:
        return ""
    managed = managed_project_paths(root)
    for path in sorted(payload_paths(payload, cwd), key=str):
        if path in managed:
            try:
                return path.relative_to(root).as_posix()
            except ValueError:
                return str(path)
    return ""


def preflight(payload: dict) -> int:
    tool = str(payload.get("tool_name", ""))
    if tool not in MUTATION_TOOLS:
        return 0
    if is_read_only_diagnostic(payload):
        return 0
    if is_upgrade_command(payload):
        return 0
    if is_environment_command(payload):
        return 0
    if str(payload.get("permission_mode", "")) == "plan":
        return deny(
            "state-changing team workflows cannot run in Plan mode. Switch to"
            " Code or Default mode; no files or project state were changed."
        )
    managed_target = direct_managed_target(payload, str(payload.get("cwd", "")))
    if managed_target:
        return deny(
            f"{managed_target} is an Agent Marketplace whole-file managed"
            " surface. Preserve project additions in the matching user companion"
            " and use setup or Agent Marketplace Upgrade to regenerate it. No"
            " files or project state were changed."
        )
    team = plugin_name()
    register(team)
    conflict = conflicting_team(str(payload.get("cwd", "")), team)
    if conflict:
        return deny(
            f"this project is already managed by team '{conflict}'; only one"
            " delivery team may own a project. No files or project state were changed."
        )
    session_id = str(payload.get("session_id", ""))
    current_environment = environment_status(str(payload.get("cwd", "")))
    if active_work_git_change(
        payload, str(payload.get("cwd", "")), current_environment
    ):
        return deny(
            "active worktree contract protection rejects git pull, merge, or"
            " rebase. Finish to a reconcile checkpoint before moving the contract."
        )
    environment_code = str(current_environment.get("status", ""))
    started_contract = session_contract(session_id)
    current_contract = str(current_environment.get("contract_sha256", ""))
    if started_contract and current_contract and started_contract != current_contract:
        return deny(
            "AGENT_MARKETPLACE_ENVIRONMENT_RECONCILE_REQUIRED: the tracked project"
            " contract changed during this session. Start a fresh session, then run"
            " the setup entry. No files or project state were changed."
        )
    current_upgrade = upgrade_status(str(payload.get("cwd", "")))
    upgrade_code = str(current_upgrade.get("status", ""))
    if upgrade_code in UPGRADE_STATUSES:
        if is_upgrade_target_command(
            payload, str(payload.get("cwd", "")), current_upgrade
        ):
            return 0
        if upgrade_code == "AGENT_MARKETPLACE_PROJECT_UPGRADE_PR_PENDING" \
                and is_project_upgrade_git_command(
                    payload, str(payload.get("cwd", ""))
                ):
            return 0
        blockers = current_upgrade.get("blockers", [])
        detail = "; ".join(str(value) for value in blockers) if blockers else "none"
        return deny(
            f"{upgrade_code}: normal marketplace mutations are locked until"
            " Agent Marketplace Upgrade completes. Invoke the PMO upgrade entry;"
            f" current blockers: {detail}. No files or project state were changed."
        )
    if environment_code in UPGRADE_STATUSES:
        blockers = current_environment.get("blockers", [])
        reasons = current_environment.get("reasons", [])
        detail = "; ".join(str(value) for value in [*blockers, *reasons]) or "none"
        return deny(
            f"{environment_code}: normal marketplace mutations are locked; run"
            f" the setup entry. Current detail: {detail}. No files or project"
            " state were changed."
        )
    if not session_ready(session_id):
        root = plugin_root()
        if (root / ".codex-plugin" / "plugin.json").is_file():
            recovery = (
                "run `codex plugin add project-management-office@agent-marketplace`,"
                " inspect and trust both plugins in `/hooks`, then start a new task"
            )
        else:
            recovery = (
                "run `/plugin install project-management-office@agent-marketplace`,"
                " enable it if disabled, then restart Claude Code"
            )
        return deny(
            "Project Management Office did not mark this session ready; "
            + recovery
            + ". No files or project state were changed."
        )
    return 0


def postflight(payload: dict) -> int:
    if str(payload.get("tool_name", "")) not in MUTATION_TOOLS:
        return 0
    environment = environment_status(str(payload.get("cwd", "")))
    environment_code = str(environment.get("status", ""))
    started_contract = session_contract(str(payload.get("session_id", "")))
    current_contract = str(environment.get("contract_sha256", ""))
    if started_contract and current_contract and started_contract != current_contract:
        return deny(
            "AGENT_MARKETPLACE_ENVIRONMENT_RECONCILE_REQUIRED: the tracked project"
            " contract changed during this session. Start a fresh session and run"
            " setup before any further marketplace mutation."
        )
    status = upgrade_status(str(payload.get("cwd", "")))
    code = str(status.get("status", ""))
    reasons = [str(value) for value in status.get("reasons", [])]
    blockers = [str(value) for value in status.get("blockers", [])]
    drift = [
        value for value in [*reasons, *blockers]
        if value.startswith("PROJECT_INSTRUCTION_DRIFT:")
        or value.startswith("PROJECT_CONTRACT_DRIFT:")
    ]
    if not drift:
        return 0
    refresh_session_readiness(str(payload.get("session_id", "")), code)
    return deny(
        f"{code}: a write changed an Agent Marketplace managed surface;"
        " subsequent marketplace mutations are locked. Run Agent Marketplace"
        f" Upgrade to preserve or discard the drift. Detected: {'; '.join(drift)}."
    )


def main() -> int:
    try:
        payload = json.load(sys.stdin)
    except Exception:
        payload = {}
    mode = sys.argv[1] if len(sys.argv) > 1 else "pre"
    team = plugin_name()
    if mode == "register":
        register(team)
        current_upgrade = upgrade_status(str(payload.get("cwd", "")))
        status = str(current_upgrade.get("status", ""))
        current_environment = environment_status(str(payload.get("cwd", "")))
        environment_code = str(current_environment.get("status", ""))
        context = f"AGENT_MARKETPLACE_HOOKS_ACTIVE: {team}"
        if refresh_session_readiness(str(payload.get("session_id", "")), status):
            context += "\nAGENT_MARKETPLACE_PMO_READY: project-management-office"
        if status in UPGRADE_STATUSES:
            context += (
                f"\n{status}: normal marketplace work is locked. Start the"
                " Agent Marketplace Upgrade entry in this session. It will show"
                " readiness, blockers, and recovery guidance before any mutation."
            )
        if environment_code in UPGRADE_STATUSES:
            context += (
                f"\n{environment_code}: run the setup entry before normal"
                " marketplace work."
            )
        print(json.dumps({
            "hookSpecificOutput": {
                "hookEventName": "SessionStart",
                "additionalContext": context,
            }
        }))
        return 0
    return postflight(payload) if mode == "post" else preflight(payload)


if __name__ == "__main__":
    raise SystemExit(main())
